#version 300 es
precision highp float;
uniform vec2 resolution;
uniform sampler2D inputTex;
uniform float amount;
out vec4 fragColor;
void main() {
    vec4 source = texture(inputTex, gl_FragCoord.xy / resolution);
    fragColor = vec4(mix(source.rgb, source.rgb * vec3(1.0, 0.5, 0.8), amount), source.a);
}
